def solve(nums, k):
    def count_less_or_equal(x):
        cnt = 0
        for num in nums:
            if num <= x:
                cnt += 1
        return cnt

    low = min(nums)
    high = max(nums)

    while low < high:
        mid = (low + high) // 2
        if count_less_or_equal(mid) < k:
            low = mid + 1
        else:
            high = mid
    return low
