```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <unordered_map>

using namespace std;

class Solution {
public:
    bool avoidShip(vector<vector<int>>& grid, int n, int m) {
        // Check if the grid is empty (no ship to avoid)
        if (n == 0 || m == 0) return true;

        // Directions for up, down, left, right
        int dx[] = {-1, 1, 0, 0};
        int dy[] = {0, 0, -1, 1};

        // Visited matrix
        vector<vector<bool>> visited(n, vector<bool>(m, false));
        queue<pair<int, int>> q;

        // Find the starting point (assuming ship is present)
        int startRow = -1, startCol = -1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 1) {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        if (startRow == -1) return true; // Ship not found

        // BFS to mark all ship parts as visited
        q.push({startRow, startCol});
        visited[startRow][startCol] = true;

        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();

            for (int i = 0; i < 4; ++i) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny] && grid[nx][ny] == 1) {
                    visited[nx][ny] = true;
                    q.push({nx, ny});
                }
            }
        }

        // After BFS, check if all ship parts are marked as visited
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    return false; // Ship not fully visited (not avoided)
                }
            }
        }

        return true;
    }
};
