from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to handle negative weights and detect negative cycles
    # Since n <= 100, we can use Bellman-Ford
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle that is reachable from s, then t is unreachable
                if t in [v for v in range(n) if dist[v] != float('inf')]:
                    return -1

    return dist[t] if dist[t] != float('inf') else -1
