#include <stdio.h>
#include <stdlib.h>

// Define a structure for the graph node
typedef struct {
    int data;
    struct Node* next;
} Node;

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to add an edge between two nodes
void addEdge(Node** graph, int src, int dest) {
    Node* newNode = createNode(dest);
    newNode->next = graph[src]->next;
    graph[src]->next = newNode;

    newNode = createNode(src);
    newNode->next = graph[dest]->next;
    graph[dest]->next = newNode;
}

// Function to check if a node is visited
int isVisited(int* visited, int node) {
    return visited[node] == 1;
}

// Function to perform depth-first search (DFS)
void DFS(Node** graph, int* visited, int node) {
    visited[node] = 1;
    Node* current = graph[node];
    while (current != NULL) {
        if (!isVisited(visited, current->data)) {
            DFS(graph, visited, current->data);
        }
        current = current->next;
    }
}

// Function to check if the graph is disconnected
int isDisconnected(Node** graph, int numNodes) {
    int* visited = (int*)malloc(numNodes * sizeof(int));
    for (int i = 0; i < numNodes; i++) {
        visited[i] = 0;
    }

    DFS(graph, visited, 0);

    // Check if any node is unvisited
    for (int i = 0; i < numNodes; i++) {
        if (!isVisited(visited, i)) {
            free(visited);
            return 1; // Graph is disconnected
        }
    }

    free(visited);
    return 0; // Graph is connected
}

// Main function
int main() {
    int numNodes;
    printf("Enter number of nodes: ");
    scanf("%d", &numNodes);

    Node** graph = (Node**)malloc(numNodes * sizeof(Node*));
    for (int i = 0; i < numNodes; i++) {
        graph[i] = createNode(i);
    }

    int edges;
    printf("Enter number of edges: ");
    scanf("%d", &edges);

    for (int i = 0; i < edges; i++) {
        int u, v;
        printf("Enter edge %d (u v): ", i + 1);
        scanf("%d %d", &u, &v);
        addEdge(graph, u, v);
    }

    if (isDisconnected(graph, numNodes)) {
        printf("Graph is disconnected.\n");
    } else {
        printf("Graph is connected.\n");
    }

    // Free memory
    for (int i = 0; i < numNodes; i++) {
        Node* current = graph[i];
        Node* next;
        while (current != NULL) {
            next = current->next;
            free(current);
            current = next;
        }
    }
    free(graph);

    return 0;
}
