class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def can_ship(capacity):
            days_needed = 1
            current_capacity = 0
            for weight in weights:
                if current_capacity + weight > capacity:
                    days_needed += 1
                    current_capacity = 0
                current_capacity += weight
                if days_needed > days:
                    return False
            return True

        left = max(weights)
        right = sum(weights)
        while left < right:
            mid = (left + right) // 2
            if can_ship(mid):
                right = mid
            else:
                left = mid + 1
        return left
```

