#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
#include <queue>

using namespace std;

// Define a struct to represent the point
struct Point {
    int x, y;
    Point(int x, int y) : x(x), y(y) {}
};

// Define a function to check if a point is valid (within bounds)
bool isValid(int x, int y, int rows, int cols) {
    return x >= 0 && x < rows && y >= 0 && y < cols;
}

// Function to perform BFS and find the shortest path from start to end
vector<Point> bfs(const vector<vector<int>>& grid, Point start, Point end) {
    int rows = grid.size();
    int cols = grid[0].size();

    queue<Point> q;
    q.push(start);
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    visited[start.x][start.y] = true;

    vector<Point> parent(rows * cols, Point{-1, -1});

    while (!q.empty()) {
        Point current = q.front();
        q.pop();

        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx == 0 && dy == 0) continue; // Skip current position
                int nx = current.x + dx;
                int ny = current.y + dy;

                if (isValid(nx, ny, rows, cols) && !visited[nx][ny] && grid[nx][ny] == 1) {
                    visited[nx][ny] = true;
                    parent[nx * cols + ny] = current;
                    q.push(Point(nx, ny));
                }
            }
        }
    }

    if (!visited[end.x][end.y]) {
        return vector<Point>{}; // No path found
    }

    // Reconstruct path
    vector<Point> path;
    Point current = end;
    while (current.x != -1 && current.y != -1) {
        path.push_back(current);
        current = parent[current.x * cols + current.y];
    }

    reverse(path.begin(), path.end());
    return path;
}

// Function to print path
void printPath(const vector<Point>& path) {
    if (path.empty()) {
        cout << "No path found." << endl;
        return;
    }
    for (const auto& p : path) {
        cout << "(" << p.x << ", " << p.y << ") ";
    }
    cout << endl;
}
