def solve(nums, k):
    # Define the helper functions for counting and sorting
    def count_values(arr):
        count = {}
        for num in arr:
            count[num] = count.get(num, 0) + 1
        return count

    def get_unique_sorted(arr):
        unique = list(set(arr))
        unique.sort()
        return unique

    # Count the number of each value
    value_counts = count_values(nums)

    # Get the unique sorted list of values
    sorted_unique = get_unique_sorted(nums)

    # Find the k-th smallest value
    for val in sorted_unique:
        if value_counts[val] >= k:
            return val
