def solve():
    def is_valid(n):
        return n == 0 or any(n % i == 0 for i in range(2, int(n**0.5) + 1))

    def count_valid_numbers(limit):
        return sum(1 for n in range(2, limit + 1) if is_valid(n))

    return count_valid_numbers(100)
```

