def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return ""

    total = 0
    count = {}

    for word in data:
        total += len(word)
        count[word] = count.get(word, 0) + 1

    for word in count:
        if count[word] > 1:
            total -= len(word)
            break

    return str(total)
```

