def solve():
    def is_connected(x, y, grid):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0:
            return False
        grid[x][y] = 0
        return is_connected(x + 1, y, grid) or is_connected(x - 1, y, grid) or is_connected(x, y + 1, grid) or is_connected(x, y - 1, grid)

    def count_components(grid):
        count = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    count += 1
                    is_connected(i, j, grid)
        return count

    grid = [[1, 1, 0], [1, 0, 0], [0, 0, 1]]
    print(count_components(grid))
