#include <iostream>
#include <vector>
#include <stack>
#include <unordered_map>
#include <unordered_set>

using namespace std;

struct Node {
    int id;
    int parent;
    int rank;
};

class UnionFind {
private:
    unordered_map<int, Node> parentMap;
    int count;

public:
    UnionFind(int n) : count(n) {
        for (int i = 0; i < n; ++i) {
            parentMap[i] = {i, i, 1};
        }
    }

    int find(int x) {
        if (parentMap[x].parent != x) {
            parentMap[x].parent = find(parentMap[x].parent);
        }
        return parentMap[x].parent;
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (parentMap[rootX].rank > parentMap[rootY].rank) {
                parentMap[rootY].parent = rootX;
            } else if (parentMap[rootX].rank < parentMap[rootY].rank) {
                parentMap[rootX].parent = rootY;
            } else {
                parentMap[rootY].parent = rootX;
                parentMap[rootX].rank++;
            }
            count--;
        }
    }

    int getComponentCount() const {
        return count;
    }
};

int main() {
    int n;
    cout << "Enter number of nodes (n): ";
    cin >> n;

    int m;
    cout << "Enter number of edges (m): ";
    cin >> m;

    UnionFind uf(n);

    for (int i = 0; i < m; ++i) {
        int u, v;
        cout << "Enter edge " << i + 1 << " (u v): ";
        cin >> u >> v;
        uf.unionSet(u, v);
    }

    cout << "Number of connected components: " << uf.getComponentCount() << endl;

    return 0;
}
