        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(r, c, path):
        if (r, c) == (goal_row, goal_col):
            return path + [(r, c)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs(nr, nc, path + [(r, c)])
                if result:
                    return result
        return None

    return dfs(start_row, start_col, [(start_row, start_col)])
