def solve(grid, start, goal):
    from collections import deque
    import heapq

    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])

    if start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols or grid[start[0]][start[1]] == '#':
        return []
    if goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs():
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque([(start[0], start[1], [start])])
        visited[start[0]][start[1]] = True

        while queue:
            r, c, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != '#':
                    new_path = path + [(nr, nc)]
                    if (nr, nc) == goal:
                        return new_path
                    visited[nr][nc] = True
                    queue.append((nr, nc, new_path))
        return []

    def a_star():
        def heuristic(r, c):
            return abs(r - goal[0]) + abs(c - goal[1])

        visited = [[False for _ in range(cols)] for _ in range(rows)]
        priority_queue = [(heuristic(start[0], start[1]), 0, start[0], start[1], [start])]
        visited[start[0]][start[1]] = True

        while priority_queue:
            _, cost, r, c, path = heapq.heappop(priority_queue)
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != '#':
                    new_cost = cost + 1
                    new_path = path + [(nr, nc)]
                    if (nr, nc) == goal:
                        return new_path
                    visited[nr][nc] = True
                    heapq.heappush(priority_queue, (new_cost + heuristic(nr, nc), new_cost, nr, nc, new_path))
        return []

    path = bfs()
    if path:
        return path
    else:
        return a_star()
