def solve(grid):
    from collections import deque

    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]
    start_found = False
    start_row, start_col = -1, -1

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'M':
                start_row, start_col = r, c
                start_found = True
                break
        if start_found:
            break

    if not start_found:
        return []

    queue = deque()
    queue.append((start_row, start_col))
    visited[start_row][start_col] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and not visited[nr][nc]:
                visited[nr][nc] = True
                parent[nr][nc] = (r, c)
                queue.append((nr, nc))

    # Reconstruct path from end to start
    end_row, end_col = -1, -1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'B':  # Baby is at 'B'
                end_row, end_col = r, c
                break
        if end_row != -1:
            break

    if end_row == -1:
        return []

    path = []
    current = (end_row, end_col)
    while current is not None:
        path.append(current)
        current = parent[current[0]][current[1]]

    path.reverse()
    return path
