def solve():
    from collections import deque

    def build_graph(n, edges):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    def bfs_shortest_path(graph, start, end):
        n = len(graph)
        distance = [-1] * n
        distance[start] = 0
        queue = deque([start])
        while queue:
            current = queue.popleft()
            for neighbor, weight in graph[current]:
                if distance[neighbor] == -1:
                    distance[neighbor] = distance[current] + weight
                    queue.append(neighbor)
        return distance[end]

    def dijkstra_shortest_path(graph, start, end):
        n = len(graph)
        import heapq
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            current_dist, current = heapq.heappop(heap)
            if current == end:
                return current_dist
            if current_dist > dist[current]:
                continue
            for neighbor, weight in graph[current]:
                if dist[neighbor] > dist[current] + weight:
                    dist[neighbor] = dist[current] + weight
                    heapq.heappush(heap, (dist[neighbor], neighbor))
        return -1

    def shortest_path(graph, start, end):
        return dijkstra_shortest_path(graph, start, end)

    def process_input(n, edges):
        graph = build_graph(n, edges)
        distances = [shortest_path(graph, i, j) for i in range(n) for j in range(n)]
        return distances

    def is_connected(graph, n):
        visited = [False] * n
        def dfs(node):
            visited[node] = True
            for neighbor, _ in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
        dfs(0)
        return all(visited)

    def find_connected_components(graph, n):
        visited = [False] * n
        components = []
        for i in range(n):
            if not visited[i]:
                stack = [i]
                visited[i] = True
                component = []
                while stack:
                    node = stack.pop()
                    component.append(node)
                    for neighbor, _ in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
                components.append(component)
        return components

    def is_valid_solution(solution):
        if solution is None or solution == "":
            return False
        if isinstance(solution, str) and solution.lower() == "none":
            return True
        return True

    def validate_input(n, edges):
        if n < 1:
            return False
        for u, v, w in edges:
            if u < 0 or u >= n or v < 0 or v >= n or w < 0 or w > 100:
                return False
        return True

    def warn_and_continue(message):
        print(f"WARNING: {message}")
        return True

    def handle_errors(n, edges):
        if not validate_input(n, edges):
            return warn_and_continue("Invalid input: n must be at least 1 and edges must be within bounds.")

    def execute(n, edges):
        if not handle_errors(n, edges):
            return None
        graph = build_graph(n, edges)
        if not is_connected(graph, n):
            return None
        components = find_connected_components(graph, n)
        if len(components) > 1:
            return None
        distances = process_input(n, edges)
        return distances

    return execute
