import sys

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    graph = [[] for _ in range(n)]
    index = 2

    for _ in range(m):
        u = int(data[index])
        v = int(data[index + 1])
        w = int(data[index + 2])
        index += 3
        graph[u].append((v, w))

    # Use Floyd-Warshall to find shortest paths between all pairs
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    for u in range(n):
        for v, w in graph[u]:
            dist[u][v] = min(dist[u][v], w)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Find the minimum path from any node to any node with minimum total weight
    min_total = INF
    for i in range(n):
        for j in range(n):
            if dist[i][j] < min_total:
                min_total = dist[i][j]

    if min_total == INF:
        print(-1)
    else:
        print(min_total)
