def solve(edges, n):
    from collections import defaultdict, deque

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with Dijkstra's algorithm for shortest path
    dist = {i: float('inf') for i in range(n)}
    dist[0] = 0
    visited = set()
    queue = deque([0])

    while queue:
        u = queue.popleft()
        if u in visited:
            continue
        visited.add(u)
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    return dist[n-1] if dist[n-1] != float('inf') else -1
