                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    for neighbor in edges[node]:
                        if neighbor not in visited:
                            stack.append(neighbor)
            return visited
        else:
            visited = set()
            queue = [start]
            while queue:
                node = queue.pop(0)
                if node not in visited:
                    visited.add(node)
                    for neighbor in edges[node]:
                        if neighbor not in visited:
