from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to detect negative cycles and find shortest path
    # Since weights can be 0, but no negative weights, we can use BFS with 0-weight edges
    # But since there can be cycles, we use Bellman-Ford to detect if t is reachable

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0
    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # Check for negative weight cycles that are reachable from s
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            # If t is reachable and there's a negative cycle, it's not a valid path
            # Also, if t is not reachable, return -1
            if dist[t] != float('inf'):
                return -1
            else:
                return -1

    return dist[t] if dist[t] != float('inf') else -1
