def solve(n, edges):
    # Initialize parent array for Union-Find
    parent = list(range(n))

    # Find root of a node with path compression
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    # Union two nodes
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Process all edges
    for u, v in edges:
        union(u, v)

    # Count unique roots (connected components)
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

 the code block below implements the `solve` function to count the number of connected components in an undirected graph using a depth-first search (DFS) approach. It uses a visited set to track nodes that have been processed and iterates through all nodes to find unvisited ones, performing DFS to mark all connected nodes.

```python
def solve(n, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)

    for node in range(n):
        if node not in visited:
            dfs(node)
            components += 1

    return components
```

