import math

def collision_free(path, obstacles):
    for x, y in path:
        if (x, y) in obstacles:
            return False
    return True

def is_valid_position(x, y, max_x, max_y):
    return 0 <= x <= max_x and 0 <= y <= max_y

def nearest_neighbor(path, obstacles):
    if not path:
        return None
    x, y = path[0]
    if (x, y) in obstacles:
        return None
    for i in range(1, len(path)):
        if (path[i][0], path[i][1]) in obstacles:
            return path[i]
    return path[0]

def steer(start, goal, max_distance):
    dx = goal[0] - start[0]
    dy = goal[1] - start[1]
    distance = math.hypot(dx, dy)
    if distance <= max_distance:
        return goal
    step = (dx / distance) * max_distance, (dy / distance) * max_distance
    return (round(start[0] + step[0]), round(start[1] + step[1]))

def path_planner(start, goal, obstacles, max_distance=2.0):
    path = [start]
    while True:
        current = path[-1]
        if current == goal:
            return path
        next_point = steer(current, goal, max_distance)
        if next_point not in obstacles and is_valid_position(*next_point, *path[0]):
            path.append(next_point)
        else:
            nearest = nearest_neighbor(path, obstacles)
            if nearest is not None:
                path = path[:path.index(nearest) + 1]
            else:
                return path
