def solve(grid, man, house, baby):
    if not grid or not man or not house or not baby:
        return []

    rows, cols = len(grid), len(grid[0])
    start = man
    end = house
    baby_pos = baby

    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= end[0] < rows and 0 <= end[1] < cols):
        return []
    if not (0 <= baby_pos[0] < rows and 0 <= baby_pos[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#':
        return []
    if grid[end[0]][end[1]] == '#':
        return []
    if grid[baby_pos[0]][baby_pos[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    visited = set()
    queue = [(start, [start])]

    while queue:
        pos, path = queue.pop(0)
        if pos == end:
            return path
        if pos in visited:
            continue
        visited.add(pos)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = pos[0]+dr, pos[1]+dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                queue.append(((nr, nc), path + [(nr, nc)]))

    return []
