def solve():
    def path_exists(current, visited, grid, rows, cols):
        if current in visited:
            return False
        visited.add(current)
        row, col = current
        if row < 0 or row >= rows or col < 0 or col >= cols:
            return False
        if grid[row][col] == '1':
            return False
        return True

    def dfs(current, path, visited, grid, rows, cols, target):
        if current == target:
            return path.copy()
        row, col = current
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            next_row, next_col = row + dr, col + dc
            if path_exists((next_row, next_col), visited, grid, rows, cols):
                path.append((next_row, next_col))
                result = dfs((next_row, next_col), path, visited, grid, rows, cols, target)
                if result:
                    return result
                path.pop()
        return None

    def get_path(start, end, grid, rows, cols):
        visited = set()
        return dfs(start, [start], visited, grid, rows, cols, end)

    def solve_maze(grid, start, end):
        rows, cols = len(grid), len(grid[0])
        path = get_path(start, end, grid, rows, cols)
        if path:
            return path
        return []

    def solution(grid, start, end):
        rows, cols = len(grid), len(grid[0])
        result = solve_maze(grid, start, end)
        return result if result else []

    return solution
